application.css:
* {
  box-sizing: border-box;
}

:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #172033;
  background: #eef3f8;
}

body {
  margin: 0;
  min-width:  eighteenrem;
}

.page-shell {
  width: min(100% - 2rem,  sixtyrem);
  margin: 0 auto;
  padding: 2.5rem 0 4rem;
}

.page-header {
  margin-bottom: 1.5rem;
}

.eyebrow {
  margin: 0 0 .35rem;
  color: #2457a6;
  font-size: .8rem;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
}

h1, h2, p {
  margin-top: 0;
}

h1 {
  margin-bottom: .5rem;
  font-size: clamp(1.8rem, 4vw, 2.7rem);
}

h2 {
  margin-bottom: 1.25rem;
  font-size: 1.35rem;
}

.intro, .muted {
  color: #526176;
}

.panel {
  margin-bottom: 1.5rem;
  padding: clamp(1.1rem, 3vw, 1.75rem);
  background: #fff;
  border: 1px solid #d5deea;
  border-radius: .8rem;
  box-shadow: 0 .35rem 1rem rgba(25, 48, 79, .06);
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.field-wide {
  grid-column: 1 / -1;
}

.field {
  display: flex;
  flex-direction: column;
  gap: .4rem;
}

label {
  font-weight: 700;
  font-size: .95rem;
}

input, select, button {
  font: inherit;
}

input, select {
  width: 100%;
  min-height: 2.75rem;
  padding: .55rem .7rem;
  color: #172033;
  background: #fff;
  border: 1px solid #8796aa;
  border-radius: .4rem;
}

input:focus, select:focus, button:focus-visible {
  outline: 3px solid #8fc7ff;
  outline-offset: 2px;
}

.primary-button, .cancel-button {
  cursor: pointer;
  border-radius: .4rem;
  font-weight: 700;
}

.primary-button {
  margin-top: 1.25rem;
  padding: .7rem 1.1rem;
  color: #fff;
  background: #174f98;
  border: 2px solid #174f98;
}

.primary-button:hover { background: #103b75; }

.message {
  margin: 1rem 0 0;
  padding: .75rem 1rem;
  border-radius: .4rem;
  font-weight: 600;
}

.error { color: #8b1e1e; background: #fff0f0; border: 1px solid #e3a6a6; }
.success { color: #145c35; background: #eaf8ef; border: 1px solid #91d0a8; }

.section-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.section-heading h2 { margin-bottom: .25rem; }
.muted { margin-bottom: .5rem; font-size: .9rem; }
.empty-state { color: #526176; }
.booking-list { display: grid; gap: .8rem; }

.booking {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem;
  border: 1px solid #c9d5e4;
  border-left: .35rem solid #2868b8;
  border-radius: .5rem;
}

.booking.cancelled { opacity: .7; border-left-color: #778397; }
.booking-details { min-width: 0; }
.booking-details p { margin: .25rem 0 0; color: #526176; overflow-wrap: anywhere; }
.booking-title { margin: 0; font-size: 1.05rem; }
.cancel-button { padding: .55rem .8rem; color: #8b1e1e; background: #fff; border: 1px solid #b94a48; white-space: nowrap; }
.cancel-button:hover { background: #fff0f0; }

@media (max-width: 42rem) {
  .page-shell { width: min(100% - 1.25rem, 60rem); padding-top: 1.5rem; }
  .form-grid { grid-template-columns: 1fr; }
  .field-wide { grid-column: auto; }
  .booking { align-items: flex-start; flex-direction: column; }
}

application.javascript:
const form = document.querySelector('#booking-form');
const nameInput = document.querySelector('#booking-name');
const emailInput = document.querySelector('#booking-email');
const dateInput = document.querySelector('#booking-date');
const timeInput = document.querySelector('#booking-time');
const typeInput = document.querySelector('#booking-type');
const list = document.querySelector('#booking-list');
const errorMessage = document.querySelector('#form-error');
const confirmation = document.querySelector('#booking-confirmation');
const emptyState = document.querySelector('#empty-state');
const bookings = [];

function getToday() {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().slice(0, 10);
}

function showMessage(element, text) {
  element.textContent = text;
  element.hidden = false;
}

function hideMessage(element) {
  element.textContent = '';
  element.hidden = true;
}

function formatBookingDate(date, time) {
  const dateValue = new Date(`${date}T${time}`);
  return dateValue.toLocaleString([], { dateStyle: 'long', timeStyle: 'short' });
}

function createBookingCard(booking) {
  const article = document.createElement('article');
  article.className = 'booking';
  article.dataset.testid = 'booking';
  article.dataset.status = booking.cancelled ? 'cancelled' : 'active';
  if (booking.cancelled) article.classList.add('cancelled');

  const details = document.createElement('div');
  details.className = 'booking-details';
  const title = document.createElement('h3');
  title.className = 'booking-title';
  title.dataset.testid = 'booking-name-display';
  title.textContent = booking.name;
  const information = document.createElement('p');
  information.textContent = `${booking.type} · ${formatBookingDate(booking.date, booking.time)} · ${booking.email}${booking.cancelled ? ' · Cancelled' : ''}`;
  details.append(title, information);

  const cancelButton = document.createElement('button');
  cancelButton.type = 'button';
  cancelButton.className = 'cancel-button';
  cancelButton.dataset.testid = 'booking-cancel';
  cancelButton.textContent = booking.cancelled ? 'Cancelled' : 'Cancel booking';
  cancelButton.disabled = booking.cancelled;
  cancelButton.addEventListener('click', () => cancelBooking(booking.id));
  article.append(details, cancelButton);
  return article;
}

function renderBookings() {
  list.replaceChildren();
  if (bookings.length === 0) {
    list.append(emptyState);
    return;
  }
  bookings.forEach((booking) => list.append(createBookingCard(booking)));
}

function cancelBooking(id) {
  const booking = bookings.find((item) => item.id === id);
  if (!booking) return;
  booking.cancelled = true;
  renderBookings();
}

function handleSubmit(event) {
  event.preventDefault();
  hideMessage(confirmation);
  hideMessage(errorMessage);
  dateInput.setCustomValidity('');

  if (dateInput.value && dateInput.value < getToday()) {
    dateInput.setCustomValidity('Choose today or a future date.');
  }

  if (!form.checkValidity()) {
    form.reportValidity();
    showMessage(errorMessage, 'Please complete all fields with valid information.');
    return;
  }

  const booking = {
    id: crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${bookings.length}`,
    name: nameInput.value.trim(),
    email: emailInput.value.trim(),
    date: dateInput.value,
    time: timeInput.value,
    type: typeInput.value,
    cancelled: false
  };
  bookings.push(booking);
  renderBookings();
  form.reset();
  dateInput.min = getToday();
  showMessage(confirmation, `Booking confirmed for ${booking.name} on ${formatBookingDate(booking.date, booking.time)}.`);
}

dateInput.min = getToday();
form.addEventListener('submit', handleSubmit);
